(function(){
  if (window.__snellInstalled__) return;
  window.__snellInstalled__ = true;
  var canvas = document.getElementById('snellCanvas');
  var ctx = canvas.getContext('2d');
  var angleSlider = document.getElementById('angleSlider');
  var angleVal = document.getElementById('angleVal');
  var n1Slider = document.getElementById('n1Slider');
  var n1Val = document.getElementById('n1Val');
  var n2Slider = document.getElementById('n2Slider');
  var n2Val = document.getElementById('n2Val');
  var out = document.getElementById('snellOut');
  var playBtn = document.getElementById('playBtn');
  var CX = canvas.width / 2, CY = canvas.height / 2;
  var D2R = Math.PI / 180;
  var running = false, pulse = 0;
  window.simState = { i: 40, n1: 1, n2: 1.5, r: 0, critical: 41.8, tir: false, time: 0, running: false };
  function compute(){
    var i = parseFloat(angleSlider.value), n1 = parseFloat(n1Slider.value), n2 = parseFloat(n2Slider.value);
    var sinI = Math.sin(i * D2R);
    var sinR = sinI * n1 / n2;
    var r = 0, tir = false;
    if (sinR > 1) { tir = true; } else { r = Math.asin(sinR) / D2R; }
    var crit = n1 > n2 ? Math.asin(n2 / n1) / D2R : 90;
    window.simState.i = i; window.simState.n1 = n1; window.simState.n2 = n2;
    window.simState.r = r; window.simState.critical = crit; window.simState.tir = tir;
    return { i: i, n1: n1, n2: n2, sinI: sinI, r: r, tir: tir, crit: crit };
  }
  function draw(){
    var p = compute();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#e0f2fe'; ctx.fillRect(0, 0, canvas.width, CY);
    ctx.fillStyle = '#fef3c7'; ctx.fillRect(0, CY, canvas.width, canvas.height - CY);
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(0, CY); ctx.lineTo(canvas.width, CY); ctx.stroke();
    ctx.setLineDash([4, 4]); ctx.strokeStyle = '#64748b';
    ctx.beginPath(); ctx.moveTo(CX, 0); ctx.lineTo(CX, canvas.height); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#0f172a'; ctx.font = '12px sans-serif';
    ctx.fillText('الوسط 1 (n1 = ' + p.n1.toFixed(2) + ')', CX + 10, 20);
    ctx.fillText('الوسط 2 (n2 = ' + p.n2.toFixed(2) + ')', CX + 10, canvas.height - 10);
    var L = 170;
    var ix = CX + L * Math.sin(p.i * D2R);
    var iy = CY - L * Math.cos(p.i * D2R);
    ctx.strokeStyle = '#dc2626'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(ix, iy); ctx.lineTo(CX, CY); ctx.stroke();
    var rxk = Math.sin(p.r * D2R), ryk = Math.cos(p.r * D2R);
    ctx.strokeStyle = '#2563eb'; ctx.lineWidth = 3;
    if (!p.tir) {
      ctx.beginPath(); ctx.moveTo(CX, CY); ctx.lineTo(CX + L * rxk, CY + L * ryk); ctx.stroke();
    } else {
      ctx.beginPath(); ctx.moveTo(CX, CY); ctx.lineTo(CX + L * Math.sin(p.i * D2R), CY - L * Math.cos(p.i * D2R)); ctx.stroke();
    }
    if (p.tir) {
      ctx.fillStyle = '#dc2626'; ctx.font = 'bold 15px sans-serif';
      ctx.fillText('انعكاس كلي (i > ℓ)', CX - 90, CY + 40);
    }
    if (running) {
      pulse += 0.04;
      var t = (pulse % 1.4) / 1.4;
      var px, py;
      if (!p.tir) {
        var rx = CX + L * rxk, ry = CY + L * ryk;
        var total = L + L;
        var d = t * total;
        if (d < L) { px = ix + (CX - ix) * d / L; py = iy + (CY - iy) * d / L; }
        else { var d2 = d - L; px = CX + (rx - CX) * d2 / L; py = CY + (ry - CY) * d2 / L; }
      } else {
        var tx = CX + L * Math.sin(p.i * D2R), ty = CY - L * Math.cos(p.i * D2R);
        var total2 = L + L;
        var d3 = t * total2;
        if (d3 < L) { px = ix + (CX - ix) * d3 / L; py = iy + (CY - iy) * d3 / L; }
        else { var d4 = d3 - L; px = CX + (tx - CX) * d4 / L; py = CY + (ty - CY) * d4 / L; }
      }
      ctx.fillStyle = '#f59e0b'; ctx.beginPath(); ctx.arc(px, py, 5, 0, Math.PI * 2); ctx.fill();
    }
    angleVal.textContent = p.i + '°';
    n1Val.textContent = p.n1.toFixed(2);
    n2Val.textContent = p.n2.toFixed(2);
    var ratio = p.tir ? '—' : (p.sinI / Math.sin(p.r * D2R)).toFixed(3);
    out.textContent = 'i = ' + p.i.toFixed(1) + '° | r = ' + (p.tir ? '—' : p.r.toFixed(1)) + '° | sin i / sin r = ' + ratio;
    window.simState.time += 0.05;
  }
  playBtn.addEventListener('click', function(){ running = !running; window.simState.running = running; playBtn.textContent = running ? 'إيقاف النبض' : 'تشغيل النبض'; });
  angleSlider.addEventListener('input', function(){});
  n1Slider.addEventListener('input', function(){});
  n2Slider.addEventListener('input', function(){});
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  function loop(){ draw(); requestAnimationFrame(loop); }
  loop();
})();
